import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.CpLciM8b.js";const k=JSON.parse('{"title":"Development guide","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/development.md","filePath":"contributing/development.md","lastUpdated":1790775300000}'),n={name:"contributing/development.md"};function d(o,e,r,h,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="development-guide" tabindex="-1">Development guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to &quot;Development guide&quot;">​</a></h1><p>This page gets you from a fresh clone to a pull request: how to set the repository up, where things live, how the tests work, and the handful of changes that touch more than one package. The rules for branches, commits and changesets are in <a href="https://github.com/AKogut/flakemetry/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>.</p><h2 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h2><p>You need Node 22.18 or later (the build toolchain requires it; the published packages still run on Node 20), pnpm (the version pinned in <code>packageManager</code>; <code>corepack enable</code> provides it), and Docker.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AKogut/flakemetry.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flakemetry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><p>That is enough for every package&#39;s tests. To run the whole product (API, worker, dashboard, object store) the way a user does:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;AUTH_SECRET=$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stack:up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><p>The dashboard signs in through GitHub only. The <a href="/flakemetry/v/2026-09-30/guide/self-hosting">self-hosting guide</a> explains the OAuth app it needs.</p><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><p>Dependencies point one way: apps depend on packages, packages depend on <code>contracts</code>, and nothing depends on an app. The published packages are the ones a user installs. Everything else ships inside the Docker images.</p><table tabindex="0"><thead><tr><th>Workspace</th><th>What it is</th><th>Published</th></tr></thead><tbody><tr><td><code>apps/api</code></td><td>Fastify service: ingestion (<code>/v1/ingest</code>, OTLP <code>/v1/traces</code>), the REST read API, badges, tRPC</td><td>no</td></tr><tr><td><code>apps/worker</code></td><td>Queue consumer: identity, scoring, rollups, clustering, AI analysis, notifications, retention</td><td>no</td></tr><tr><td><code>apps/web</code></td><td>Next.js dashboard</td><td>no</td></tr><tr><td><code>apps/docs</code></td><td>This documentation site (VitePress)</td><td>no</td></tr><tr><td><code>packages/contracts</code></td><td>zod schemas shared by everything: ingestion payloads, config, policy, REST surface</td><td>yes</td></tr><tr><td><code>packages/core</code></td><td>Pure domain logic: test identity, fingerprints, flaky scoring. No I/O</td><td>yes</td></tr><tr><td><code>packages/sdk</code></td><td>Recording, OTLP export, delivery, CI detection</td><td>yes</td></tr><tr><td><code>packages/reporter</code></td><td><code>@flakemetry/playwright-reporter</code></td><td>yes</td></tr><tr><td><code>packages/vitest-reporter</code></td><td><code>@flakemetry/vitest-reporter</code></td><td>yes</td></tr><tr><td><code>packages/jest-reporter</code></td><td><code>@flakemetry/jest-reporter</code></td><td>yes</td></tr><tr><td><code>packages/cli</code></td><td><code>flakemetry</code> command: upload, run, junit, import, flaky, quarantine, doctor</td><td>yes</td></tr><tr><td><code>packages/pytest-flakemetry</code></td><td>pytest plugin (Python, released separately to PyPI)</td><td>no</td></tr><tr><td><code>packages/db</code></td><td>Prisma schema, migrations, seed, client</td><td>no</td></tr><tr><td><code>packages/queries</code></td><td>Tenant-scoped reads and writes shared by the API and the dashboard</td><td>no</td></tr><tr><td><code>packages/ai</code></td><td>LLM providers, scrubbing, root-cause prompts</td><td>no</td></tr><tr><td><code>packages/notify</code></td><td>Slack, Discord, email and signed webhook delivery, tracker issues</td><td>no</td></tr><tr><td><code>packages/plugin-host</code></td><td>Loads plugins from <code>FLAKEMETRY_PLUGINS</code> and runs their hooks under a deadline</td><td>no</td></tr><tr><td><code>packages/storage</code></td><td>Object store for artifacts (S3, MinIO, in-memory)</td><td>no</td></tr><tr><td><code>packages/eslint-config</code></td><td>Shared lint rules</td><td>no</td></tr><tr><td><code>packages/tsconfig</code></td><td>Shared TypeScript presets</td><td>no</td></tr><tr><td><code>packages/build-config</code></td><td>Shared tsdown build presets; published packages are checked with publint and arethetypeswrong</td><td>no</td></tr></tbody></table><p>A test run travels like this:</p><ol><li>A reporter records the run with the SDK and sends it: OTLP to <code>/v1/traces</code>, or JSON to <code>/v1/ingest</code>. The SDK never fails the test run over a delivery problem.</li><li><code>apps/api/src/app.ts</code> authenticates the token, validates against <code>contracts</code>, enqueues the batch in Postgres and answers <code>202</code>.</li><li><code>apps/worker/src/processor.ts</code> takes the batch (<code>FOR UPDATE SKIP LOCKED</code>), resolves each test&#39;s identity, stores executions, scores, updates rollups, and hands failures to <code>rca.ts</code>.</li><li>The dashboard and the REST API read through <code>packages/queries</code>, which scopes every query to one project.</li></ol><h2 id="everyday-commands" tabindex="-1">Everyday commands <a class="header-anchor" href="#everyday-commands" aria-label="Permalink to &quot;Everyday commands&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                  # everything, through turbo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @flakemetry/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # one package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # prettier is a separate CI step from eslint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # all packages at once, no cache</span></span></code></pre></div><p>Workspace packages are consumed through their built <code>dist</code>. After changing <code>contracts</code> or <code>core</code>, build it before type-checking whatever imports it.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><strong>Point the tests at a database.</strong> Tests that need Postgres skip themselves when <code>DATABASE_URL</code> is unset, so a run without it is green while testing about half of the code. <code>REQUIRE_DB=1</code> turns an unreachable database into a failure instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;postgresql://flakemetry:flakemetry@localhost:5432/flakemetry?schema=public&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  REQUIRE_DB=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>Each package migrates its own schema (<code>flakemetry_test_&lt;package&gt;</code>), so packages can run in parallel without seeing each other&#39;s rows. Running them concurrently and uncached is deliberate: that is how interference between suites shows up.</p><p><strong>Conventions the suite relies on:</strong></p><ul><li>Tests sit next to the code in <code>src/__tests__</code>.</li><li><code>packages/core</code> uses property tests (<code>fast-check</code>) for identity and scoring. A property that fails once in CI has found an input the code gets wrong; treat it as a bug, not as noise.</li><li>Several tests guard a promise rather than a function: every <code>FLAKEMETRY_</code> variable the code reads is documented, every project query is tenant-scoped, every REST route is in the generated reference and the OpenAPI document, web and worker receive the same policy variables, the Policy form has an input for every field it saves, and reporter peer ranges do not narrow. When one fails, fix the drift it found. Do not loosen the test.</li><li>A new test should fail without the change it covers. Revert the fix, watch it fail, put the fix back.</li></ul><p><strong>Checks that run the real thing</strong> live in <code>.github/workflows</code>: <code>stack</code> runs the README quickstart, <code>reporters</code> runs every reporter inside its real runner against a live API and worker, <code>backup</code> destroys and restores the database, and <code>e2e</code> runs nightly.</p><h2 id="changes-that-cross-packages" tabindex="-1">Changes that cross packages <a class="header-anchor" href="#changes-that-cross-packages" aria-label="Permalink to &quot;Changes that cross packages&quot;">​</a></h2><p><strong>A new policy field.</strong> Add it to <code>POLICY_DEFAULTS</code>, <code>POLICY_FIELDS</code> and <code>projectPolicyInputSchema</code> in <code>packages/contracts/src/policy.ts</code>, including its environment variable. Add the column in <code>packages/db</code>, the input on the Policy page (<code>apps/web/src/app/projects/[projectId]/settings/policy/page.tsx</code>) and in <code>updateProjectPolicy</code>, and pass the variable to both web and worker in both compose files. Guard tests fail until every one of those is done.</p><p><strong>A database change.</strong> Edit <code>packages/db/prisma/schema.prisma</code>, then <code>pnpm --filter @flakemetry/db exec prisma migrate dev --name &lt;what&gt;</code>. Migrations must be additive: the self-hosted upgrade path is &quot;rebuild and restart&quot;, with no manual step.</p><p><strong>A REST route.</strong> Describe it in <code>REST_ENDPOINTS</code> (<code>packages/contracts/src/rest.ts</code>) and register it in <code>apps/api</code>. The API reference and <code>/openapi.json</code> are generated from that table, and a test fails if the table and the registered routes disagree.</p><p><strong>A notification event.</strong> Add it to <code>NOTIFICATION_EVENTS</code> in <code>packages/contracts</code> and <code>NOTIFICATION_TYPES</code> in <code>packages/notify</code> (a test keeps them equal), emit it from the worker, and give it a label on the notifications settings page.</p><p><strong>A published package.</strong> Add a changeset (<code>pnpm changeset</code>) describing the change from the point of view of someone who installs it.</p><h2 id="asking-for-help" tabindex="-1">Asking for help <a class="header-anchor" href="#asking-for-help" aria-label="Permalink to &quot;Asking for help&quot;">​</a></h2><p>Questions and half-formed ideas go to <a href="https://github.com/AKogut/flakemetry/discussions" target="_blank" rel="noreferrer">Discussions</a>. If an issue labelled <a href="https://github.com/AKogut/flakemetry/labels/good%20first%20issue" target="_blank" rel="noreferrer"><code>good first issue</code></a> needs more context than it has, ask on the issue before starting.</p>`,31)])])}const g=t(n,[["render",d]]);export{k as __pageData,g as default};
